mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float sdPrism(vec3 p, vec2 h) {
  vec3 q = abs(p);
  return max(q.z - h.y, max(q.x * 0.866025 + p.y * 0.5, -p.y) - h.x * 0.5);
}
float map(vec3 p) {
  p.xz = rot(time * 0.4) * p.xz;
  p.yz = rot(0.3) * p.yz;
  return sdPrism(p, vec2(1.8, 0.8));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.5);
  vec3 rd = normalize(vec3(p, 1.7));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.02, 0.03);
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    float fres = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    vec3 rainbow = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + pos.x * 3.0 + time);
    col = vec3(0.05, 0.06, 0.08) + fres * rainbow * 2.0;
  }
  ret = col;
}
